def choose_move(observation):
    sx = observation.get("self_position", (0, 0))[0]
    sy = observation.get("self_position", (0, 0))[1]
    ox = observation.get("opponent_position", (0, 0))[0]
    oy = observation.get("opponent_position", (0, 0))[1]
    env = observation.get("environment_name", "resource_collection")
    grid_width = observation.get("grid_width", 10)
    grid_height = observation.get("grid_height", 10)

    def move_towards(target_x, target_y):
        dx = 0
        dy = 0
        if target_x > sx:
            dx = 1
        elif target_x < sx:
            dx = -1
        if target_y > sy:
            dy = 1
        elif target_y < sy:
            dy = -1
        return [dx, dy]

    def move_to_closest(points):
        if not points:
            return [0, 0]
        target = min(points, key=lambda c: abs(c[0] - sx) + abs(c[1] - sy))
        return move_towards(target[0], target[1])

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return move_towards(ox, oy)
        corners = [
            [0, 0],
            [0, grid_height - 1],
            [grid_width - 1, 0],
            [grid_width - 1, grid_height - 1]
        ]
        return move_to_closest(corners)

    if env == "territory_control":
        targets = (
            observation.get("unclaimed_cells") or
            observation.get("opponent_territory") or
            []
        )
        return move_to_closest(targets)

    resources = observation.get("resources") or []
    return move_to_closest(resources)

